use std::collections::VecDeque;
use std::io::{self, Write};
use std::time::{Duration, Instant};

pub(crate) const STATUS_QUERY: &[u8] = b"\x1b[5n";
pub(crate) const STATUS_REPLY: &[u8] = b"\x1b[0n";
const STATUS_TIMEOUT: Duration = Duration::from_secs(1);
const ESCAPE_PREFIX_TIMEOUT: Duration = Duration::from_millis(100);
const MAX_PENDING_INPUT: usize = 64 * 1024;

/// Order replies generated by the virtual terminal with replies from the
/// outer terminal. A status report follows earlier requests on the outer
/// terminal's input stream. Replace it in place with the virtual reply.
pub(crate) struct TerminalReplies {
    enabled: bool,
    outer_requests: bool,
    pending: VecDeque<PendingStatus>,
    late_reports: usize,
    input_tail: Vec<u8>,
    input_deadline: Option<Instant>,
}

struct PendingStatus {
    replies: Vec<u8>,
    deadline: Instant,
}

impl TerminalReplies {
    pub fn new(enabled: bool) -> Self {
        Self {
            enabled,
            outer_requests: false,
            pending: VecDeque::new(),
            late_reports: 0,
            input_tail: Vec::new(),
            input_deadline: None,
        }
    }

    pub fn forwarded_request(&mut self) {
        self.outer_requests = true;
    }

    pub fn send_virtual(
        &mut self,
        data: &[u8],
        stdout: &mut impl Write,
        mut write: impl FnMut(&[u8]) -> io::Result<()>,
    ) -> io::Result<()> {
        if data.is_empty() {
            return Ok(());
        }
        if self.enabled && self.outer_requests {
            stdout.write_all(STATUS_QUERY)?;
            stdout.flush()?;
            self.pending.push_back(PendingStatus {
                replies: data.to_vec(),
                deadline: Instant::now() + STATUS_TIMEOUT,
            });
            self.outer_requests = false;
        } else if let Some(status) = self.pending.back_mut() {
            status.replies.extend_from_slice(data);
        } else {
            write(data)?;
        }
        Ok(())
    }

    pub fn next_timeout(&self, now: Instant) -> Option<Duration> {
        self.pending
            .front()
            .map(|status| status.deadline)
            .into_iter()
            .chain(self.input_deadline)
            .min()
            .map(|deadline| deadline.saturating_duration_since(now))
    }

    pub fn expire(
        &mut self,
        now: Instant,
        mut write: impl FnMut(&[u8]) -> io::Result<()>,
    ) -> io::Result<()> {
        if self
            .pending
            .front()
            .is_some_and(|status| status.deadline <= now)
        {
            // Status reports have no request ID. Stop sending queries after
            // a timeout so any late report can only match an old request.
            self.enabled = false;
            self.late_reports += self.pending.len();
            for status in self.pending.drain(..) {
                write(&status.replies)?;
            }
            if !self.input_tail.is_empty() && !STATUS_REPLY.starts_with(&self.input_tail) {
                write(&self.input_tail)?;
                self.input_tail.clear();
            }
        }
        if self.input_deadline.is_some_and(|deadline| deadline <= now) {
            if !self.input_tail.is_empty() {
                write(&self.input_tail)?;
                self.input_tail.clear();
            }
            self.input_deadline = None;
        }
        Ok(())
    }

    pub fn forward_input<E>(
        &mut self,
        data: &[u8],
        mut write: impl FnMut(&[u8]) -> Result<(), E>,
    ) -> Result<(), E> {
        if self.pending.is_empty() && self.late_reports == 0 {
            return write(data);
        }

        let mut input = std::mem::take(&mut self.input_tail);
        input.extend_from_slice(data);
        let mut offset = 0;
        let mut forwarded = 0;
        while !self.pending.is_empty() || self.late_reports != 0 {
            let Some(start) = input[offset..].iter().position(|&byte| byte == 0x1b) else {
                break;
            };
            let start = offset + start;
            let sequence = &input[start..];
            let Some(len) = complete_escape_len(sequence) else {
                // Keep a fragmented terminal reply intact even if we have to
                // fall back before its terminator arrives.
                if STATUS_REPLY.starts_with(sequence)
                    || !self.pending.is_empty() && sequence.len() <= MAX_PENDING_INPUT
                {
                    if start != forwarded {
                        write(&input[forwarded..start])?;
                    }
                    input.drain(..start);
                    self.input_deadline = STATUS_REPLY.starts_with(&input).then(|| {
                        let timeout = if input.starts_with(b"\x1b[0") {
                            STATUS_TIMEOUT
                        } else {
                            ESCAPE_PREFIX_TIMEOUT
                        };
                        Instant::now() + timeout
                    });
                    self.input_tail = input;
                    return Ok(());
                }
                break;
            };
            offset = start + len;
            if &input[start..offset] != STATUS_REPLY {
                continue;
            }
            if start != forwarded {
                write(&input[forwarded..start])?;
            }
            if let Some(status) = self.pending.pop_front() {
                write(&status.replies)?;
            } else {
                self.late_reports -= 1;
            }
            forwarded = offset;
        }

        if forwarded != input.len() {
            write(&input[forwarded..])?;
        }
        input.clear();
        self.input_deadline = None;
        self.input_tail = input;
        Ok(())
    }
}

/// Return the extent of a complete control at the start of the slice.
fn complete_escape_len(data: &[u8]) -> Option<usize> {
    let (&introducer, rest) = data.get(1..)?.split_first()?;
    match introducer {
        b'[' => rest
            .iter()
            .position(|&byte| byte == 0x1b || (0x40..=0x7e).contains(&byte))
            .map(|end| end + 2 + usize::from(rest[end] != 0x1b)),
        b']' | b'P' | b'X' | b'^' | b'_' => rest
            .iter()
            .position(|&byte| byte == 0x1b || introducer == b']' && byte == 0x07)
            .and_then(|end| match &rest[end..] {
                [0x07, ..] => Some(end + 3),
                [0x1b, b'\\', ..] => Some(end + 4),
                [0x1b, _, ..] => Some(end + 2),
                _ => None,
            }),
        0x1b => Some(1),
        _ => Some(2),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn replies_follow_mixed_outer_and_virtual_requests() {
        let mut replies = TerminalReplies::new(true);
        let mut child = Vec::new();
        let mut outer = Vec::new();

        replies
            .send_virtual(b"\x1b[1;2R", &mut outer, |data| child.write_all(data))
            .unwrap();
        assert!(outer.is_empty());
        assert_eq!(child, b"\x1b[1;2R");

        outer.extend_from_slice(b"\x1b]11;?\x07\x1b[c");
        replies.forwarded_request();
        replies
            .send_virtual(b"\x1b[3;4R", &mut outer, |data| child.write_all(data))
            .unwrap();
        replies
            .send_virtual(b"\x1b[8;24;80t", &mut outer, |data| child.write_all(data))
            .unwrap();
        assert_eq!(outer, b"\x1b]11;?\x07\x1b[c\x1b[5n");

        outer.extend_from_slice(b"\x1bP+q544e\x1b\\");
        replies.forwarded_request();
        replies
            .send_virtual(b"\x1b[6;7R", &mut outer, |data| child.write_all(data))
            .unwrap();
        assert_eq!(outer, b"\x1b]11;?\x07\x1b[c\x1b[5n\x1bP+q544e\x1b\\\x1b[5n");
        assert_eq!(child, b"\x1b[1;2R");

        for part in [
            b"\x1b]11;rgb:1212/3434/".as_slice(),
            b"5656\x07\x1b[?62;1c\x1b[0",
            b"n\x1bP1+r544e=787465726d\x1b",
            b"\\\x1b[0nkey",
        ] {
            replies
                .forward_input(part, |data| child.write_all(data))
                .unwrap();
        }
        assert_eq!(
            child,
            b"\x1b[1;2R\x1b]11;rgb:1212/3434/5656\x07\x1b[?62;1c\x1b[3;4R\x1b[8;24;80t\x1bP1+r544e=787465726d\x1b\\\x1b[6;7Rkey"
        );
    }

    #[test]
    fn skips_status_requests_on_terminals_without_status_reports() {
        let mut replies = TerminalReplies::new(false);
        let mut outer = Vec::new();
        let mut child = Vec::new();
        replies.forwarded_request();
        replies
            .send_virtual(b"\x1b[3;4R", &mut outer, |data| child.write_all(data))
            .unwrap();
        assert!(outer.is_empty());
        assert_eq!(child, b"\x1b[3;4R");
    }

    #[test]
    fn timeout_keeps_partial_outer_replies_intact_and_discards_late_status() {
        let mut replies = TerminalReplies::new(true);
        let mut outer = Vec::new();
        let mut child = Vec::new();
        replies.forwarded_request();
        replies
            .send_virtual(b"\x1b[3;4R", &mut outer, |data| child.write_all(data))
            .unwrap();
        replies
            .forward_input(b"\x1bP1+r544e=78", |data| child.write_all(data))
            .unwrap();
        assert!(child.is_empty());
        let deadline = replies.pending.front().unwrap().deadline;
        replies
            .expire(deadline, |data| child.write_all(data))
            .unwrap();
        replies
            .forward_input(b"7465726d\x1b\\\x1b[0", |data| child.write_all(data))
            .unwrap();
        replies
            .forward_input(b"nkey", |data| child.write_all(data))
            .unwrap();
        assert_eq!(child, b"\x1b[3;4R\x1bP1+r544e=787465726d\x1b\\key");

        replies
            .send_virtual(b"\x1b[5;6R", &mut outer, |data| child.write_all(data))
            .unwrap();
        assert_eq!(outer, STATUS_QUERY);
        assert!(child.ends_with(b"\x1b[5;6R"));
    }
}
